onMovementEnded: {
var diff = contentX - preContentX
if (Math.abs(diff) < (base.width / 10)) {
base.page_movement_duration = Math.abs(diff) / 6
setPageIndex(pageIndex)
} else {
base.page_movement_duration = (base.width - Math.abs(diff)) / 6
if (diff < 0) {
if (pageIndex > 0) setPageIndex(pageIndex - 1)
} else {
if (pageIndex < (pageCount - 1)) setPageIndex(pageIndex + 1)
}
}
}
