function checkIndex(x, y, margin) {
var i
i = Math.floor((x + margin) / base.width)
if (i !== pageIndex && 0 <= i && i < pageCount) {
base.page_movement_duration = base.width / 4
gridViewBinding(i)
setPageIndex(i)
return getIndexAt(x + margin, y)
}
i = Math.floor((x - margin) / base.width)
if (i !== pageIndex && 0 <= i && i < pageCount) {
base.page_movement_duration = base.width / 4
gridViewBinding(i)
setPageIndex(i)
return getIndexAt(x - margin, y);
}
return getIndexAt(x - margin, y);
