function calcIconXPosition(index, page) {
return (index % 2) * base.cellWidth + page * base.width + base.cellWidth / 2
}
function calcIconYPosition(index) {
return (Math.floor(index / 2) % rowCount) * base.cellHeight + base.cellHeight / 2
