loc.startY = calcIconYPosition(index)
}
function startPagingIconAnimation(from, to) {
var fromPage = Math.floor(from / base.iconCountPerPage)
var toPage = Math.floor(to / base.iconCountPerPage)
if (fromPage == toPage) {
return
}
var toStartIndex
var toEndIndex
if (fromPage < toPage) {
toStartIndex = toPage * base.iconCountPerPage
toEndIndex   = toStartIndex - 1
} else {
toStartIndex = (toPage + 1) * base.iconCountPerPage - 1
toEndIndex   = toStartIndex + 1
}
loc.pagingStartX = calcIconXPosition(toStartIndex, toPage)
loc.pagingStartY = calcIconYPosition(toStartIndex)
loc.pagingEndX   = calcIconXPosition(toEndIndex, fromPage)
loc.pagingEndY   = calcIconYPosition(toEndIndex)
loc.pagingFilename  = list.get(toStartIndex).file_name
loc.pagingBackcolor = list.get(toStartIndex).back_color
loc.pagingIconname  = list.get(toStartIndex).icon_name
base.delegatePagingId = list.get(toStartIndex).id
loc.pagingId = toStartIndex
}
